package com.example.smartpantry;
import android.content.*;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.google.android.material.dialog.MaterialAlertDialogBuilder;import com.example.smartpantry.adapter.PantryAdapter;import com.example.smartpantry.data.DatabaseHelper;import com.example.smartpantry.model.PantryItem;
public class MainActivity extends AppCompatActivity implements PantryAdapter.Listener{DatabaseHelper db;PantryAdapter adapter;TextView empty;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);db=new DatabaseHelper(this);empty=findViewById(R.id.emptyText);RecyclerView rv=findViewById(R.id.pantryRecycler);rv.setLayoutManager(new LinearLayoutManager(this));adapter=new PantryAdapter(db.getPantryItems(),this);rv.setAdapter(adapter);findViewById(R.id.addFab).setOnClickListener(v->startActivity(new Intent(this,AddEditIngredientActivity.class)));findViewById(R.id.navPantry).setOnClickListener(v->{});findViewById(R.id.navSuggestions).setOnClickListener(v->startActivity(new Intent(this,SuggestedRecipesActivity.class)));findViewById(R.id.navSettings).setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));refresh();}@Override protected void onResume(){super.onResume();if(db!=null)refresh();}void refresh(){adapter.setData(db.getPantryItems());empty.setVisibility(adapter.getItemCount()==0?android.view.View.VISIBLE:android.view.View.GONE);}@Override public void edit(PantryItem x){Intent i=new Intent(this,AddEditIngredientActivity.class);i.putExtra("id",x.id);i.putExtra("name",x.name);i.putExtra("quantity",x.quantity);i.putExtra("unit",x.unit);i.putExtra("expiry",x.expiryDate);startActivity(i);}@Override public void delete(PantryItem x){new MaterialAlertDialogBuilder(this).setTitle("Delete ingredient?").setMessage("Remove "+x.name+" from the pantry?").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{db.deletePantry(x.id);refresh();}).show();}}
